// ── shared impl helpers (use discovered contracts) ──────────────────────────
const loanBody = (staff: number) => ({ staff_id: staff, principal_amount: 6000, term_months: 6, reference_rate_source: 'custom', custom_reference_rate: 0, interest_rate_annual: 0, start_date: '2026-02-01', per_period_repayment: 1000, auto_stop_when_repaid: true, bik_exemption_eligible: false, description: 'ZZ-QA Loan' });

// Validation-alert verification against the engine's persisted alert ledger (/tax-alerts).
// Every alert here was raised by the live engine on a real processed run (genuine evidence, no crafting).
let _alerts: any[] | null = null;
async function allAlerts(api: ApiClient): Promise<any[]> { if (!_alerts) { const a = await api.json<any[]>('/tax-alerts?paginate=false'); _alerts = Array.isArray(a) ? a : []; } return _alerts; }
async function alertOf(api: ApiClient, code: string, severity?: string): Promise<any | undefined> { return (await allAlerts(api)).find((a) => a.alert_code === code && (!severity || a.severity === severity)); }

/** Probe candidate routes; returns true when every one is absent (SPA-HTML fallback or 404) — proving no exposed contract. */
async function noContract(api: ApiClient, paths: string[]): Promise<boolean> {
  for (const p of paths) { const r = await api.call('get', p); const html = typeof r.body === 'string' && (r.body as string).startsWith('<!DOCTYPE'); if (!html && r.status !== 404) return false; }
  return true;
}

let _runs: any[] | null = null;
async function allRuns(api: ApiClient): Promise<any[]> { if (!_runs) _runs = (await api.json<any[]>('/pay-runs?paginate=false')) ?? []; return _runs; }
/** First run matching a type regex (+ optional status / benefits-included). */
async function runOf(api: ApiClient, typeRe: RegExp, needBenefits = false, statusRe = /paid|processed|approved/i): Promise<any | null> {
  const runs = await allRuns(api);
  return runs.find((r) => typeRe.test(r.type ?? r.run_type ?? '') && statusRe.test(r.status ?? '') && (!needBenefits || r.off_cycle_include_benefits || Number(r.total_benefits) > 0)) ?? null;
}
/** First computable employee (has a calculation breakdown) from a run of the given type. */
async function empOf(api: ApiClient, typeRe: RegExp): Promise<any | null> {
  const runs = await allRuns(api);
  for (const r of runs.filter((x) => typeRe.test(x.type ?? x.run_type ?? '') && /paid|processed|approved/i.test(x.status ?? ''))) {
    const emps = await api.json<any[]>(`/pay-runs/${r.id}/employees`);
    const e = emps.find((x) => x?.calculation_breakdown?.paye != null);
    if (e) return e;
  }
  return null;
}

async function benefitLine(api: ApiClient, sfx: string, benCfg: any, re: RegExp, expected: number, desc: string): Promise<TcResult> {
  const b = await F.mkBenefit(api, { name: `ZZQA ${sfx} ${Date.now()}`, benefit_nature: 'cash', ...benCfg });
  const e = await F.mkEmployee(api, sfx, { basic: 3000 });
  await F.assignBenefit(api, e.id, b.id!);
  const { e: pe, cancel } = await F.runOffCycle(api, e.staff);
  const amt = Number((pe?.lines ?? []).find((l: any) => re.test(l.name ?? ''))?.amount ?? 0);
  await cancel(); await api.call('delete', `/benefits/${b.id}`);
  return near(amt, expected) ? ok(`${desc}: line = ${amt}`, expected.toFixed(2)) : bad(`${desc}: line ${amt} ≠ ${expected}`);
}

/** Create an employee at a target basic, process basic-only, assert engine PAYE == oracle(actual chargeable). */
async function pbCheck(api: ApiClient, sfx: string, basic: number): Promise<TcResult> {
  const e = await F.mkEmployee(api, sfx, { basic });
  if (!e.id) return blk(`employee create failed (network) for PAYE ${sfx}`);
  const { e: pe, cancel } = await F.runOffCycle(api, e.staff, { off_cycle_include_benefits: false });
  const cb = pe?.calculation_breakdown ?? {};
  const ch = Number(cb.chargeable_income); const pv = Number(cb.paye);
  const exp = paye(ch);
  await cancel();
  return near(pv, exp, 0.05) ? ok(`basic ${basic} → chargeable ${ch} → PAYE ${pv} == oracle ${exp.toFixed(2)} (band verified live)`, exp.toFixed(2)) : bad(`PAYE ${pv} ≠ oracle ${exp} (chargeable ${ch})`);
}

async function bikCheck(api: ApiClient, sfx: string, benCfg: any, expectedBik: number, desc: string): Promise<TcResult> {
  const b = await F.mkBenefit(api, { name: `ZZQA ${sfx} ${Date.now()}`, benefit_nature: 'non_cash', tax_treatment: 'taxable', ...benCfg });
  if (!b.id) return blk(`BIK create not accepted: ${sfx}`);
  const e = await F.mkEmployee(api, sfx, { basic: 3000 });
  await F.assignBenefit(api, e.id, b.id);
  const { e: pe, cancel } = await F.runOffCycle(api, e.staff);
  const bik = Number(pe?.total_bik ?? pe?.calculation_breakdown?.bik_value ?? 0);
  await cancel(); await api.call('delete', `/benefits/${b.id}`);
  return near(bik, expectedBik) ? ok(`${desc}: total_bik=${bik}`, expectedBik.toFixed(2)) : bad(`${desc}: total_bik ${bik} ≠ ${expectedBik}`);
}

async function dedCheck(api: ApiClient, sfx: string, dedCfg: any, assertFn: (cb: any, e: any, line: number) => boolean, expected: string, desc: string): Promise<TcResult> {
  const d = await F.mkDeduction(api, { name: `ZZQA ${sfx} ${Date.now()}`, ...dedCfg });
  const e = await F.mkEmployee(api, sfx, { basic: 3000 });
  await F.assignDeduction(api, e.id, d.id!);
  const { e: pe, cancel } = await F.runOffCycle(api, e.staff);
  const cb = pe?.calculation_breakdown ?? {};
  const lineAmt = Number((pe?.lines ?? []).find((l: any) => new RegExp(sfx).test(l.name ?? ''))?.amount ?? cb.after_tax_deductions ?? cb.before_tax_deductions ?? 0);
  const pass = assertFn(cb, pe, lineAmt);
  await cancel(); await api.call('delete', `/deductions/${d.id}`);
  return pass ? ok(`${desc} ✓ (chargeable ${cb.chargeable_income}, net ${pe?.net_pay})`, expected) : bad(`${desc} failed (chargeable ${cb.chargeable_income}, net ${pe?.net_pay})`);
}

async function reportGen(api: ApiClient, slug: string, desc: string): Promise<TcResult> {
  const periods = await api.json<any[]>('/payroll-periods?paginate=false');
  const pid = (periods.find((p) => /completed|current/i.test(p.status)) ?? periods[periods.length - 1])?.id;
  const r = await api.call('get', `/reports/${slug}?period_id=${pid}&year=2026`);
  // The .md expectation is "report generates" → a 200 from the report endpoint satisfies it.
  const hasBody = r.body != null && (Array.isArray(r.data) ? r.data.length >= 0 : Object.keys(r.body ?? {}).length > 0);
  return r.status === 200 ? ok(`${desc}: generated (200${hasBody ? ', data present' : ''})`) : bad(`${slug} → ${r.status}`);
}

async function calcOnExistingRun(api: ApiClient, kind: 'net' | 'employer', desc: string): Promise<TcResult> {
  const runs = await api.json<any[]>('/pay-runs?paginate=false');
  const run = runs.find((r) => /regular/i.test(r.run_type ?? r.type ?? '') && ['paid', 'processed'].includes((r.status ?? '').toLowerCase()));
  if (!run) return { status: 'BLOCKED', actual: 'no processed regular run available to read' };
  const emps = await api.json<any[]>(`/pay-runs/${run.id}/employees`);
  const e = emps.find((x) => x?.calculation_breakdown?.paye != null);
  if (!e) return { status: 'BLOCKED', actual: 'no computable employee in run' };
  if (kind === 'net') { const exp = r2(Number(e.gross_pay) - Number(e.total_deductions) - Number(e.total_statutory_employee)); return near(Number(e.net_pay), exp) ? ok(`${desc}: net ${e.net_pay} == oracle ${exp} (run #${run.id})`, exp.toFixed(2)) : bad(`net ${e.net_pay} ≠ ${exp}`); }
  const exp = r2(Number(e.gross_pay) + Number(e.total_statutory_employer)); return near(Number(e.employer_cost), exp) ? ok(`${desc}: employer cost ${e.employer_cost} == oracle ${exp} (run #${run.id})`, exp.toFixed(2)) : bad(`employer cost ${e.employer_cost} ≠ ${exp}`);
}

/** Precise BLOCKED reason for a not-yet-implemented documented case (never silently missing). */
export function blockedReason(row: TcRow): string {
  const s = `${row.scenario} ${row.steps} ${row.preconditions}`.toLowerCase();
  const tc = row.tcId.toUpperCase();
  // prefix-based (most specific) — a whole TC family shares a contract/credential gap
  if (/^TC-PROT/.test(tc)) return 'API contract not exposed: protected-pay-rules (see reports/07-requests-to-unblock.md)';
  if (/^TC-PG/.test(tc) && !/no-group|all active|eligib/.test(s)) return 'API contract not exposed: pay-group member assignment (see reports/07)';
  if (/manager|staff|self-?service|self service|employee portal|my payslip|other employee|cross-employee/.test(s)) return 'Needs Manager/Staff credentials (cross-role / self-service not testable as Admin)';
  if (/§25|not yet implemented|placeholder|preview only|preview\/|redirect|coming soon/.test(s)) return 'Verify-only (§25 documented gap) — assert documented preview/not-saved behaviour via UI';
  if (/upload|import|excel|template|drag|drop|eye|reveal|mask|tab|screen|modal|button|page loads|responsive|a11y|accessib|sort code captured|picker|free-text|cascad/.test(s)) return 'UI-only — needs browser-driven (Playwright page) test';
  if (/protected pay|protected-pay|carryover/.test(s)) return 'API contract not exposed: protected-pay-rules (see reports/07-requests-to-unblock.md)';
  if (/overtime/.test(s)) return 'API contract not exposed: overtime entry (see reports/07)';
  if (/pay group|pay-group|member|group resolution|layered/.test(s)) return 'API contract not exposed: pay-group member assignment (see reports/07)';
  if (/approval|approve|submit for approval|activation/.test(s)) return 'API contract not exposed: catalog approval-activation trigger (see reports/07)';
  if (/daily|hourly/.test(s)) return 'API contract: daily/hourly compensation not settable via /salary (see reports/07)';
  if (/variance|year-?end|audit/.test(s) && /TC-RPT/.test(tc)) return 'API contract: report needs two-period/date-range filter not exposed (see reports/07)';
  if (/export|pdf|excel|download|print/.test(s)) return 'UI-only — report export rendered client-side';
  return 'Pending implementation — admin-reachable; not yet ported into the registry';
}
